CREATE OR REPLACE FUNCTION public.normalize_financial_group_entry() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF new.person_id='00000000-0000-0000-0000-000000000000' THEN new.person_id:=NULL; END IF; RETURN new; END $$; CREATE TRIGGER aaa_normalize_party BEFORE INSERT ON public.financial_entries FOR EACH ROW EXECUTE FUNCTION public.normalize_financial_group_entry();
CREATE OR REPLACE FUNCTION public.check_financial_group_total() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE gid uuid; target numeric; actual numeric; BEGIN gid:=CASE WHEN tg_table_name='financial_groups' THEN new.id ELSE new.group_id END; IF gid IS NULL THEN RETURN new; END IF; SELECT total INTO target FROM public.financial_groups WHERE id=gid; SELECT coalesce(sum(amount),0) INTO actual FROM public.financial_entries WHERE group_id=gid AND NOT canceled; IF actual<>target THEN RAISE EXCEPTION 'Parcelas devem fechar o total do grupo.'; END IF; RETURN new; END $$;
CREATE CONSTRAINT TRIGGER group_total_check AFTER INSERT ON public.financial_groups DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_financial_group_total();
CREATE CONSTRAINT TRIGGER entry_total_check AFTER INSERT OR UPDATE ON public.financial_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_financial_group_total();